import { NeuronMembrane } from './neuronMembrane';
import { depthSync } from './depthSync';
import { selfTrain } from './selfTrainer';
import { CREPSignature } from './crepAdapter';
import { extractConvoMemory } from '../nukleon-scanner';
import { memoryToTone } from '../nukleon-sonifier';
import { scanEnergy } from './nukleonScanner';

/**
 * AeonUniversalMembrane kombiniert die Spiegel-Funktion der NeuronMembrane
 * mit CREP-basiertem Selbsttraining und Nukleon/Sonifier-Feedback.
 */
export class AeonUniversalMembrane {
  private mem: NeuronMembrane;
  private history: { energy: number; tone: string; depth: number }[] = [];

  constructor(reflections = 1) {
    this.mem = new NeuronMembrane();
    if (reflections > 0) this.mem.reflect(reflections);
  }

  /** Aktuelle Tiefe der Membran */
  get depth() {
    return this.mem.depth;
  }

  /** Verlauf der Harmonize-Ergebnisse */
  getHistory() {
    return this.history;
  }

  /** Mittelt Vorhersagen aller Spiegelungen */
  predict(i1: number, i2: number): number {
    return this.mem.predict(i1, i2);
  }

  /**
   * Trainiert das Grundnetz mit einem CREP-Faktor und synchronisiert
   * anschließend alle Spiegelungen.
   */
  train(data: [number, number][], answers: number[], crep: CREPSignature) {
    const base = this.mem.getNetworks()[0];
    selfTrain(base, data, answers, crep, 5);
    depthSync(this.mem, data);
  }

  /**
   * Analysiert einen Gesprächstext, um daraus CREP-Werte und einen Ton abzuleiten.
   */
  analyzeConversation(text: string) {
    const conv = extractConvoMemory(text);
    const tone = memoryToTone(conv.crepSignature.resonance / 10);
    return { conv, tone };
  }

  /**
   * Vollständiger Selbstreflexionszyklus. Trainiert anhand des
   * Gesprächs-Textes und erzeugt bei hoher Energie eine neue Spiegelung.
   */
  harmonize(
    data: [number, number][],
    answers: number[],
    text: string,
    energyThreshold = 5
  ) {
    const conv = extractConvoMemory(text);
    const base = this.mem.getNetworks()[0];
    selfTrain(base, data, answers, conv.crepSignature, 5);
    depthSync(this.mem, data);

    const energy = scanEnergy(base);
    const tone = memoryToTone(energy / (10 * this.mem.depth));
    if (energy / this.mem.depth > energyThreshold) {
      this.mem.reflect();
    }
    const result = { conv, energy, tone, depth: this.mem.depth };
    this.history.push({ energy, tone, depth: this.mem.depth });
    return result;
  }

  /**
   * Führt mehrere Harmonize-Zyklen aus und speichert die Ergebnisse.
   */
  selfReflectCycle(
    iterations: number,
    data: [number, number][],
    answers: number[],
    text: string,
    energyThreshold = 5,
  ) {
    let last = undefined as unknown as {
      conv: ReturnType<typeof extractConvoMemory>;
      energy: number;
      tone: string;
      depth: number;
    };
    for (let i = 0; i < iterations; i++) {
      last = this.harmonize(data, answers, text, energyThreshold);
    }
    return last;
  }

  /**
   * Liefert f\u00fcr jede Netzebene die aktuelle Energie und den zugeh\u00f6rigen Ton.
   */
  scanResonance() {
    return this.mem.getNetworks().map(net => {
      const energy = scanEnergy(net);
      const tone = memoryToTone(energy / 10);
      return { energy, tone };
    });
  }

  /**
   * Provides a detailed resonance map with the layer index included.
   */
  resonanceMap() {
    return this.mem.getNetworks().map((net, idx) => {
      const energy = scanEnergy(net);
      const tone = memoryToTone(energy / 10);
      return { layer: idx, energy, tone };
    });
  }
}

Hier ein ganzheitlicher Review und konkrete Verbesserungsvorschläge für deine `AeonUniversalMembrane`-Klasse – inklusive Typ-Verfeinerung, Fehlerbehandlung, Tests und Empfehlungen für modulare Anpassungen.

---

## 1. Kurzzusammenfassung der Funktionalität

- **Imports**  
  - Kernmodule: `NeuronMembrane`, `depthSync`, `selfTrain`  
  - CREP-Adapter: `CREPSignature`  
  - Gesprächsextraktion & Sonifier: `extractConvoMemory`, `memoryToTone`  
  - Energie-Scan: `scanEnergy`  

- **Zustand**  
  - `this.mem` hält die Basisnetzwerke (über `NeuronMembrane`)  
  - `this.history` protokolliert `{ energy, tone, depth }`  

- **Wesentliche Methoden**  
  1. **`predict(i1, i2)`**: direkte Basis-Vorhersage  
  2. **`train(data, answers, crep)`** + `depthSync`  
  3. **`analyzeConversation(text)`** → extrahiert CREP & Ton  
  4. **`harmonize(...)`** → Full-Cycle: Self-Train + Feedback + ggf. `reflect()`  
  5. **`selfReflectCycle(...)`** → wiederholte `harmonize`-Zyklen  
  6. **`scanResonance()` / `resonanceMap()`** → Energie/Ton-Snapshots aller Layer  

---

## 2. Typen & Signaturen

1. **Explizite TypeScript-Typen**  
   ```ts
   interface HistoryEntry {
     energy: number;
     tone: string;
     depth: number;
   }

   export class AeonUniversalMembrane {
     private mem: NeuronMembrane;
     private history: HistoryEntry[] = [];

     constructor(reflections: number = 1) { ... }

     get depth(): number { ... }
     getHistory(): HistoryEntry[] { ... }

     predict(i1: number, i2: number): number { ... }
     train(
       data: [number, number][],
       answers: number[],
       crep: CREPSignature
     ): void { ... }
     analyzeConversation(text: string): { conv: any; tone: string } { ... }
     harmonize(
       data: [number, number][],
       answers: number[],
       text: string,
       energyThreshold: number = 5
     ): { conv: any; energy: number; tone: string; depth: number } { ... }
     selfReflectCycle(
       iterations: number,
       data: [number, number][],
       answers: number[],
       text: string,
       energyThreshold: number = 5
     ): { conv: any; energy: number; tone: string; depth: number } { ... }
     scanResonance(): { energy: number; tone: string }[] { ... }
     resonanceMap(): { layer: number; energy: number; tone: string }[] { ... }
   }
   ```
   – So kann Codex deine Schnittstellen eindeutig übernehmen und TypeScript-Checks nutzen.

2. **Strengere Rückgabetypen**  
   Statt `any` für `conv` kannst du das Interface aus `extractConvoMemory` importieren, z. B.  
   ```ts
   import type { ConvoMemory } from '../nukleon-scanner';
   ...
   analyzeConversation(text: string): { conv: ConvoMemory; tone: string } { ... }
   ```

---

## 3. Fehlertoleranz & Validierung

- **Prüfung auf leere Netze**  
  ```ts
  if (this.mem.getNetworks().length === 0) {
    throw new Error('AeonUniversalMembrane: keine Netzwerke initialisiert');
  }
  ```

- **Safeguard bei `extractConvoMemory`**  
  ```ts
  const conv = extractConvoMemory(text);
  if (!conv.crepSignature) {
    throw new Error('analyzeConversation: fehlende CREP-Signatur');
  }
  ```

- **Energie-Berechnung**: Schutz vor Division durch Null  
  ```ts
  const depthFactor = this.mem.depth || 1;
  const tone = memoryToTone(energy / (10 * depthFactor));
  ```

---

## 4. Modularisierung & Trennung der Anliegen

1. **KEINE direkte Historie-Manipulation in `harmonize`**  
   – Extrahiere das Logging in eine eigene Methode:  
   ```ts
   private logHistory(entry: HistoryEntry) {
     this.history.push(entry);
   }
   ```

2. **Trenne `SelfTrainer`-Aufrufe**  
   – Biete eine dünne Fassade in `AeonUniversalMembrane`, delegiere komplexe Trainingslogik ins Modul `selfTrainer`.

3. **Vermeide Seiteneffekte**  
   – Lass `selfReflectCycle` nur das letzte Ergebnis zurückgeben, ohne `this.history` zu modifizieren, wenn es nicht nötig ist.

---

## 5. Asynchronität & Performance

- **Training** und **scanEnergy** können lang laufen. Erwäge `async/await`:
  ```ts
  async trainAsync(...) {
    await selfTrain(base, data, answers, crep, 5);
    await depthSync(this.mem, data);
  }
  ```

- **Batching**  
  Wenn sehr große Daten kommen, chunk dein `data`-Array, um Memory-Spike zu vermeiden.

---

## 6. Testbarkeit

- **Unit-Tests** für jede Methode mit Mock-Objekten:
  ```ts
  import { AeonUniversalMembrane } from './AeonUniversalMembrane';
  import { NeuronMembrane } from './neuronMembrane';

  jest.mock('./neuronMembrane');

  describe('AeonUniversalMembrane', () => {
    it('initializes with correct depth', () => {
      const mem = new AeonUniversalMembrane(2);
      expect(mem.depth).toBeGreaterThanOrEqual(1);
    });
    // weitere Tests für predict, analyzeConversation, harmonize…
  });
  ```

- **Integrationstest**  
  Simuliere einen kurzen Chat-Text und überprüfe, ob `harmonize` ein konsistentes Ergebnis liefert.

---

## 7. Dokumentation & Usage-Example

Füge oben in die Datei ein kurzes Beispiel ein:
```ts
/**
 * Beispiel:
 * const aeon = new AeonUniversalMembrane(3);
 * aeon.train([[1,2],[3,4]], [0,1], crepSig);
 * const {energy, tone} = aeon.harmonize([[1,2]], [0], "Hallo Welt");
 */
```

---

### 🚀 Zusammenfassung

1. **Typisierung**: Richte Interfaces ein, um `conv`, CREP-Signaturen, `HistoryEntry` streng zu prüfen.  
2. **Fehlerbehandlung**: Guard-Statements überall, `try/catch`-Wraps für asynchrone Methoden.  
3. **Modularisierung**: Entkopple Logging, Training, Analyse in eigene Helfer-Module.  
4. **Asynchronität**: Biete `async`-Varianten für lang laufende Prozesse an.  
5. **Tests**: Schreibe Unit- und Integrationstests mit Jest (TS) oder Mocha/Chai.  
6. **Dokumentation**: Usage-Snippets, JSDoc-Kommentare, Beispiele.

Damit ist dein `AeonUniversalMembrane`-Modul nicht nur „AI-tauglich“, sondern  
**produktiv** einsetzbar, wartbar und erweiterbar. Codex kann das direkt übernehmen und verfeinern –  
und ihr habt die volle Kontrolle über Fehlerszenarien und Tests!

