**`autoCommitAgent.js`**  
```js
import cron from 'node-cron';
import { exec } from 'child_process';
import fs from 'fs';
import yaml from 'js-yaml';

const cfg = yaml.load(fs.readFileSync('agents/autoCommitAgent.yaml', 'utf8')).autoCommitAgent;

function runSelfLearn() {
  // Locking via flock (alternativ: eigene Logik)
  const lockfile = cfg.lockfile;
  exec(`flock -n ${lockfile} -c "npm run selflearn"`, (err, stdout, stderr) => {
    if (err) {
      console.error('SelfLearn-Job gescheitert:', err.message);
      scheduleRetry(1);
    } else {
      console.log('SelfLearn-Job erfolgreich:', stdout);
    }
  });
}

let retryCount = 0;
function scheduleRetry(attempt) {
  if (attempt > cfg.backoff.retries) return console.error('Maximale Retry-Versuche erreicht.');
  const delayMin = Math.pow(cfg.backoff.factor, attempt) * 10; // z.B. 10, 20, 40 ...
  console.log(`Retry in ${delayMin} Minuten (Versuch ${attempt})`);
  setTimeout(() => {
    runSelfLearn();
  }, delayMin * 60 * 1000);
}

cron.schedule(cfg.schedule, () => {
  console.log('Starte SelfLearn-Job laut Cron…');
  runSelfLearn();
});
```

