## 3. Robuste Fehler- & Backoff-Strategie in Python (ArchivAeon)

```python
import time
import yaml
from datetime import datetime
from functools import wraps

def retry_on_exception(retries=3, backoff_factor=2):
    def deco(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            delay = 1
            while attempt < retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempt += 1
                    print(f"[{func.__name__}] Fehler: {e}. Retry {attempt}/{retries} in {delay}s.")
                    time.sleep(delay)
                    delay *= backoff_factor
            raise RuntimeError(f"{func.__name__} fehlgeschlagen nach {retries} Versuchen.")
        return wrapper
    return deco

class ArchivAeon:
    @retry_on_exception(retries=5, backoff_factor=3)
