## **2. Plug-in-Loader-Service mit Isolierung/Resonanz-Feedback**

```ts
// pluginLoader.ts (erweitert)
import vm from 'vm2';
import yaml from 'js-yaml';
import fs from 'fs';
import path from 'path';
import chokidar from 'chokidar';

const PLUGIN_DIR = path.join(__dirname, 'plugins');
const manifests = new Map<string, any>();
const modules = new Map<string, any>();
const apiVersion = "1.1";

function loadPlugin(name: string) {
  const manifestPath = path.join(PLUGIN_DIR, name, 'manifest.yaml');
  const manifest = yaml.load(fs.readFileSync(manifestPath, 'utf8'));
  // --- API-Version-Check
  if (manifest.apiVersion !== apiVersion) throw new Error(`API mismatch for ${name}`);
  manifests.set(name, manifest);
  // --- VM2 für Sandboxing
  const entryPath = path.join(PLUGIN_DIR, name, manifest.entry);
  delete require.cache[require.resolve(entryPath)];
  const pluginCode = fs.readFileSync(entryPath, 'utf8');
  const vmInstance = new vm.NodeVM({
    console: "inherit",
    sandbox: { pluginMeta: manifest },
    require: { external: true }
  });
  modules.set(name, vmInstance.run(pluginCode, entryPath));
  console.log(`🔌 Plug-in ${name}@${manifest.version} loaded (sandboxed).`);
}

chokidar.watch(`${PLUGIN_DIR}/*/manifest.yaml`).on('all', (_, p) => {
  const name = path.basename(path.dirname(p));
  try { loadPlugin(name); } catch (e) { console.error(e); }
});

fs.readdirSync(PLUGIN_DIR).forEach(dir => loadPlugin(dir));

export function getPlugin(name: string) { return modules.get(name); }
export function listPlugins() { return Array.from(manifests.values()); }
```

**Sandboxing = echte Sicherheit**
**API-Versioning & Error-Feedback = Dev-Experience**
**Plug-in-Registry:** Für Community-Votes, Changelogs, Security-Review!

