    "entry": {"type":"string"},
    "apiVersion": {"type":"string"},
    "permissions": {"type":"array","items":{"type":"string"}}
  }
}
```

### 3.2 Validation-Skript (Node)
```js
// scripts/validateManifests.js
import fs from 'fs';
import path from 'path';
import Ajv from 'ajv';

const ajv = new Ajv();
const schema = JSON.parse(fs.readFileSync('schemas/pluginManifest.schema.json', 'utf8'));
const validate = ajv.compile(schema);

const pluginsDir = path.join(__dirname, '../plugins');
fs.readdirSync(pluginsDir).forEach(dir => {
  const mf = path.join(pluginsDir, dir, 'manifest.yaml');
  const manifest = require('js-yaml').load(fs.readFileSync(mf, 'utf8'));
  const valid = validate(manifest);
  if (!valid) console.error(`Manifest invalid for ${dir}:`, validate.errors);
  else console.log(`${dir} manifest OK`);
});
```

