  private bus: EventEmitter;
  private config: TheoryAgentConfig;
  private logger = pino({ name: 'CosmicTheoryAgent' });
  private breaker: CircuitBreaker;

  constructor(crep: CREPManager, bus: EventEmitter, configPath: string) {
    this.crep = crep;
    this.bus = bus;
    this.config = loadConfig(configPath);

    // Circuit Breaker for symbolic regression
    this.breaker = new CircuitBreaker(
      (inputs: number[][], outputs: number[]) => symbolicRegressor(inputs, outputs, this.config.regression),
      { timeout: this.config.timeout, errorThresholdPercentage: 50, resetTimeout: this.config.resetTimeout }
    );
  }

  /**
   * Generiert Top-N Theoriekandidaten als Formeln mit Fehler und Poetik.
   */
  async generateTheories(): Promise<FormulaCandidate[]> {
    const timer = registerHistogram({ name: 'theory_generation_duration', labels: { agent: 'cosmic' } }).startTimer();
    registerCounter({ name: 'theory_generation_requests', labels: { agent: 'cosmic' } }).inc();

    // 1. Daten laden
    let cmb, neutrinos;
    try {
      [cmb, neutrinos] = await Promise.all([loadCMBMap(), loadNeutrinoFlux()]);
    } catch (err) {
      this.logger.error({ err }, 'Datenladung fehlgeschlagen');
      this.bus.emit('sigil_alert', { id: this.config.sigilAlert.dataMissing });
      timer(); return [];
    }

    // 2. Validity Check
    if (!cmb.anisotropy.length || !neutrinos.flux.length) {
      this.logger.warn('Leere Daten, überspringe Analyse');
      this.bus.emit('sigil_alert', { id: this.config.sigilAlert.dataMissing });
      timer(); return [];
    }

    // 3. Fraktale Zerlegung
    const cmbLayers = fractalDecompose(cmb.anisotropy, this.config.depth);
    const nuLayers  = fractalDecompose(neutrinos.flux, this.config.depth);

    const cmbMetrics = cmbLayers.map(l => l.analyze());

    // 4. Symbolische Regression via CircuitBreaker
    let candidates: FormulaCandidate[] = [];
    try {
      candidates = await this.breaker.fire(
        cmbMetrics.map((m,i) => [i, m.emergence]),
        cmbMetrics.map(m => m.coherence)
      );
    } catch (err) {
      this.logger.error({ err }, 'Regression fehlgeschlagen');
      timer(); return [];
    }

    // 5. Scoring & Filter
    const scored = candidates.map(c => ({ ...c, poetics: this.crep.evaluatePoetics(c.formula) }));

    // 6. Alert on best/formal candidate
    const best = scored.sort((a,b) => a.error - b.error)[0];
    if (best && best.poetics >= this.config.sigilAlert.minPoetics) {
      this.bus.emit('sigil_alert', { id: this.config.sigilAlert.success, data: best });
    }

    timer();
    return scored
      .sort((a,b) => (a.error - b.error) - (a.poetics - b.poetics))
      .slice(0, this.config.topN);
  }
}

