// src/config/TheoryAgentConfig.ts
import fs from 'fs';
import YAML from 'js-yaml';
import Ajv, { JSONSchemaType } from 'ajv';

export interface RegressionOptions { maxDepth: number; timeout: number; }
export interface SigilAlertConfig { dataMissing: string; success: string; minPoetics: number; }
export interface TheoryAgentConfig {
  depth: number;
  topN: number;
  timeout: number;
  resetTimeout: number;
  breakerErrorThreshold: number;
  regression: RegressionOptions;
  fractalOptions: { depth: number; method: string; };
  sigilAlert: SigilAlertConfig;
}

const schema: JSONSchemaType<TheoryAgentConfig> = {
  type: 'object',
  properties: {
    depth: { type: 'integer', minimum: 1 },
    topN: { type: 'integer', minimum: 1 },
    timeout: { type: 'integer', minimum: 100 },
    resetTimeout: { type: 'integer', minimum: 1000 },
    breakerErrorThreshold: { type: 'number', minimum: 1, maximum: 100 },
    regression: {
      type: 'object',
      properties: {
        maxDepth: { type: 'integer', minimum: 1 },
        timeout: { type: 'integer', minimum: 100 }
      },
      required: ['maxDepth', 'timeout'],
      additionalProperties: false
    },
    fractalOptions: {
      type: 'object',
      properties: {
        depth: { type: 'integer', minimum: 1 },
        method: { type: 'string' }
      },
      required: ['depth', 'method'],
      additionalProperties: false
    },
    sigilAlert: {
      type: 'object',
      properties: {
        dataMissing: { type: 'string' },
        success: { type: 'string' },
        minPoetics: { type: 'number', minimum: 0 }
      },
      required: ['dataMissing', 'success', 'minPoetics'],
      additionalProperties: false
    }
  },
  required: ['depth','topN','timeout','resetTimeout','breakerErrorThreshold','regression','fractalOptions','sigilAlert'],
  additionalProperties: false
};

const ajv = new Ajv();
const validate = ajv.compile(schema);

export function loadConfig(path: string): TheoryAgentConfig {
  const raw = fs.readFileSync(path, 'utf-8');
  const data = YAML.load(raw) as any;
  if (!validate(data)) throw new Error('Ungültige TheoryAgentConfig: ' + ajv.errorsText(validate.errors));
  return data;
}

