    const cacheKey = `${this.config.depth}-${this.config.regression.maxDepth}`;
    if (this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey)!;
      // Rückgabe und Hintergrund-Refresh
      this.refreshCache(cacheKey, ctx, span).catch(err => this.logger.error(err));
      span.end();
      return cached;
    }

    const histogram = registerHistogram({ name: 'theory_generation_duration', labels: { agent: 'cosmic', version: this.agentVersion } });
    const timer = histogram.startTimer();
