// packages/ui/src/audio/PhiTone.ts

export const PHI = (1 + Math.sqrt(5)) / 2;
export const PI = Math.PI;
export const E = Math.E;

/**
 * Mappt CREP-Metriken auf eine Frequenz (Hz).
 * Optionale: MandalaMode für harmonische Obertöne.
 */
export function crepToFrequency({ coherence, resonance, emergence, poetics }: Record<string, number>, base = 220, mode: 'phi' | 'pi' | 'e' | 'mandala' = 'phi') {
  switch (mode) {
    case 'phi':
      return base * Math.pow(PHI, coherence);
    case 'pi':
      return base * Math.pow(PI, resonance / 2.5); // zart moduliert
    case 'e':
      return base * Math.pow(E, emergence / 2.5);
    case 'mandala':
      return (
        base * Math.pow(PHI, coherence) +
        base * Math.pow(PI, resonance) / 2 +
        base * Math.pow(E, emergence) / 4 +
        10 * Math.sin(poetics * 6.2831)
      );
    default:
      return base;
  }
}

/** Spielt einen Sinus-Ton */
export function playPhiTone(frequency: number, duration = 0.5, volume = 0.15) {
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();

  osc.type = "sine";
  osc.frequency.value = frequency;
  gain.gain.value = volume;

  osc.connect(gain);
  gain.connect(ctx.destination);

  osc.start();
  osc.stop(ctx.currentTime + duration);
  osc.onended = () => ctx.close();
}

2. React-Hook: useCREPTone

Für UI-Komponenten – spielt Ton automatisch oder auf Trigger, mit Return für Accessibility/Fallback.

// packages/ui/src/audio/useCREPTone.ts
import { useRef, useCallback } from "react";
import { crepToFrequency, playPhiTone } from "./PhiTone";

export interface CREPMetrics {
  coherence: number;
  resonance: number;
  emergence: number;
  poetics: number;
}

export function useCREPTone(
  crep: CREPMetrics,
  mode: "phi" | "pi" | "e" | "mandala" = "phi"
) {
  const lastPlayed = useRef<number>(0);

  const play = useCallback(
    (opts?: { volume?: number; duration?: number }) => {
      const freq = crepToFrequency(crep, 220, mode);
      playPhiTone(freq, opts?.duration || 0.5, opts?.volume || 0.15);
      lastPlayed.current = freq;
      return freq;
    },
    [crep, mode]
  );

  // Optional: Frequenz als String für Screenreader/visual fallback
  return { play, lastPlayed };
}

