import React, { useEffect, useState } from 'react';
import type { TheoryBus } from '../agents/CosmicTheoryAgent';
import YAML from 'yaml';

interface Alert { id: string; data?: any; requestId: string; }

export function SigilAlert({ bus }: { bus: TheoryBus }) {
  const [alerts, setAlerts] = useState<Alert[]>([]);

  useEffect(() => {
    const handler = (ctx: any) => {
      setAlerts(prev => [{ id: ctx.id, data: ctx.data, requestId: ctx.requestId }, ...prev]);
    };
    bus.on('sigil_alert', handler);
    return () => { bus.off('sigil_alert', handler); };
  }, [bus]);

  return (
    <div className="sigil-alert-container" role="alert" aria-live="polite">
      {alerts.map(a => (
        <div key={a.requestId} className="sigil-alert">
          <strong>Sigil:</strong> {a.id}
          <button
            onClick={() => {
              const blob = new Blob([YAML.stringify({ sigil_id: a.id, data: a.data })], { type: 'text/yaml' });
              const url = URL.createObjectURL(blob);
              const aTag = document.createElement('a');
              aTag.href = url;
              aTag.download = `${a.id}.yaml`;
              aTag.click();
            }}
          >Download Sigil</button>
        </div>
      ))}
    </div>
  );
}
