import fs from 'fs';
import path from 'path';
import Ajv, { JSONSchemaType } from 'ajv';

/**
 * Config-Interface für CosmicTheoryAgent
 */
export interface TheoryAgentConfig {
  version: string;
  depth: number;
  topN: number;
  cacheSize: number;
  breakerErrorThreshold: number;
  resetTimeout: number;
  rollingWindowMs: number;
  rollingBuckets: number;
  regression: {
    maxDepth: number;
    timeout: number;
  };
  fractalOptions: {
    depth: number;
    method: 'wavelet' | 'boxCount' | 'fourier';
  };
  pythonFallback: {
    url: string;
    timeout: number;
  };
  sigilAlert: {
    dataMissing: string;
    success: string;
    minPoetics: number;
  };
}

// JSON-Schema zur Validierung
const theoryConfigSchema: JSONSchemaType<TheoryAgentConfig> = {
  type: 'object',
  properties: {
    version: { type: 'string' },
    depth: { type: 'integer', minimum: 1 },
    topN: { type: 'integer', minimum: 1 },
    cacheSize: { type: 'integer', minimum: 1 },
    breakerErrorThreshold: { type: 'number', minimum: 1, maximum: 100 },
    resetTimeout: { type: 'integer', minimum: 1000 },
    rollingWindowMs: { type: 'integer', minimum: 1 },
    rollingBuckets: { type: 'integer', minimum: 1 },
    regression: {
      type: 'object',
      properties: {
        maxDepth: { type: 'integer', minimum: 1 },
        timeout: { type: 'integer', minimum: 1000 }
      },
      required: ['maxDepth', 'timeout'],
      additionalProperties: false
    },
    fractalOptions: {
      type: 'object',
      properties: {
        depth: { type: 'integer', minimum: 1 },
        method: { type: 'string', enum: ['wavelet', 'boxCount', 'fourier'] }
      },
      required: ['depth', 'method'],
      additionalProperties: false
    },
    pythonFallback: {
      type: 'object',
      properties: {
        url: { type: 'string', format: 'uri' },
        timeout: { type: 'integer', minimum: 1000 }
      },
      required: ['url', 'timeout'],
      additionalProperties: false
    },
    sigilAlert: {
      type: 'object',
      properties: {
        dataMissing: { type: 'string' },
        success: { type: 'string' },
        minPoetics: { type: 'number', minimum: 0, maximum: 1 }
      },
      required: ['dataMissing', 'success', 'minPoetics'],
      additionalProperties: false
    }
  },
  required: ['version','depth','topN','cacheSize','breakerErrorThreshold','resetTimeout','rollingWindowMs','rollingBuckets','regression','fractalOptions','pythonFallback','sigilAlert'],
  additionalProperties: false
};

const ajv = new Ajv({ allErrors: true, useDefaults: true });
const validate = ajv.compile(theoryConfigSchema);

/**
 * Lädt und validiert die Agenten-Konfiguration (YAML oder JSON)
 * @param filePath Pfad zur Config-Datei
 */
export function loadConfig(filePath: string): TheoryAgentConfig {
  const ext = path.extname(filePath).toLowerCase();
  const raw = fs.readFileSync(filePath, 'utf-8');
  let data: any;

  if (ext === '.json') {
    data = JSON.parse(raw);
  } else if (ext === '.yaml' || ext === '.yml') {
    // yaml library import falls benötigt
    const YAML = require('yaml');
    data = YAML.parse(raw);
  } else {
    throw new Error(`Unsupported config format: ${ext}`);
  }

  if (!validate(data)) {
    throw new Error('Invalid TheoryAgentConfig:\n' + ajv.errorsText(validate.errors));
  }

  return data;
}                                                                                                                                                                                  Ich habe das TheoryAgentConfig-Modul komplett ausgearbeitet:

    TypeScript-Interface für TheoryAgentConfig mit allen Feldern deiner YAML/JSON.

