### 2. **ThreeDPyramid-Komponente**

```tsx
// packages/ui/src/components/ThreeDPyramid.tsx
import React from "react";
import { Canvas } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import type { Layer } from "@aeonai/common/layers/Layer";

function LayerCube({ layer, pos = [0, 0, 0] }) {
  return (
    <group position={pos}>
      <mesh>
        <boxGeometry args={[layer.weight, layer.weight, layer.weight]} />
        <meshStandardMaterial color={`hsl(${layer.level * 36}, 70%, 60%)`} />
      </mesh>
      {/* Children as a horizontal row */}
      {layer.children?.map((c, i) => (
        <LayerCube
          key={c.id}
          layer={c}
          pos={[
            (i - layer.children.length / 2) * 2 * layer.weight,
            -2 * layer.weight,
            0,
          ]}
        />
      ))}
    </group>
  );
}

export function ThreeDPyramid({ root }: { root: Layer }) {
  return (
    <Canvas camera={{ position: [0, 10, 20], fov: 60 }}>
      <ambientLight intensity={0.6} />
      <pointLight position={[10, 20, 10]} intensity={0.8} />
      <LayerCube layer={root} />
      <OrbitControls />
    </Canvas>
  );
}
