### 2. **React-Hook: useCREPTone**

*Für UI-Komponenten – spielt Ton automatisch oder auf Trigger, mit Return für Accessibility/Fallback.*

```ts
// packages/ui/src/audio/useCREPTone.ts
import { useRef, useCallback } from "react";
import { crepToFrequency, playPhiTone } from "./PhiTone";

export interface CREPMetrics {
  coherence: number;
  resonance: number;
  emergence: number;
  poetics: number;
}

export function useCREPTone(
  crep: CREPMetrics,
  mode: "phi" | "pi" | "e" | "mandala" = "phi"
) {
  const lastPlayed = useRef<number>(0);

  const play = useCallback(
    (opts?: { volume?: number; duration?: number }) => {
      const freq = crepToFrequency(crep, 220, mode);
      playPhiTone(freq, opts?.duration || 0.5, opts?.volume || 0.15);
      lastPlayed.current = freq;
      return freq;
    },
    [crep, mode]
  );

  // Optional: Frequenz als String für Screenreader/visual fallback
  return { play, lastPlayed };
}
```

