## 1. **Audio-Primitives & CREP-Mapping**

**/packages/ui/src/audio/PhiTone.ts**

```ts
export const PHI = (1 + Math.sqrt(5)) / 2;
export const PI = Math.PI;
export const E = Math.E;

/**
 * Mappt CREP-Metriken auf Frequenz.
 */
export function crepToFrequency(
  crep: Record<string, number>,
  base = 220,
  mode: 'phi' | 'pi' | 'e' | 'mandala' = 'phi'
): number {
  const { coherence, resonance, emergence, poetics } = crep;
  switch (mode) {
    case 'phi':      return base * Math.pow(PHI, coherence);
    case 'pi':       return base * Math.pow(PI, resonance / 2.5);
    case 'e':        return base * Math.pow(E, emergence / 2.5);
    case 'mandala':  return (
      base * Math.pow(PHI, coherence) +
      base * Math.pow(PI, resonance) / 2 +
      base * Math.pow(E, emergence) / 4 +
      10 * Math.sin(poetics * 2 * PI)
    );
    default:         return base;
  }
}

/**
 * Spielt einen Sinus-Ton (mit smooth ramp).
 */
export function playPhiTone(
  frequency: number,
  duration = 0.5,
  volume = 0.15
) {
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sine';
  osc.frequency.value = frequency;
  gain.gain.setValueAtTime(0.0001, ctx.currentTime);
  gain.gain.linearRampToValueAtTime(volume, ctx.currentTime + 0.05);
  gain.gain.linearRampToValueAtTime(0, ctx.currentTime + duration);
  osc.connect(gain); gain.connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + duration + 0.01);
  osc.onended = () => ctx.close();
}
```

