import React from 'react';
import { useCREPTone, CREPMetrics } from '../audio/useCREPTone';

export function CREPSoundButton({
  crep,
  label = '▶️ CREP-Klang',
  mode = 'phi'
}: { crep: CREPMetrics; label?: string; mode?: 'phi'|'pi'|'e'|'mandala' }) {
