  return (
    <div>
      <button
        className="px-4 py-2 bg-indigo-600 text-white rounded focus:ring"
        onClick={() => play()}
        aria-label={`${label} (Freq: ${lastFreq.current?.toFixed(1) || '?'} Hz)`}
      >
        {label}
      </button>
      <span
        className="ml-2 text-xs text-gray-500"
        aria-live="polite"
        aria-atomic="true"
      >
        {lastFreq.current
          ? `Frequenz: ${lastFreq.current.toFixed(1)} Hz`
          : 'Noch kein Ton'}
      </span>
    </div>
  );
}
