import { playPhiTone, crepToFrequency } from './PhiTone';
import type { CREPMetrics } from './useCREPTone';

/**
 * Spielt für jedes Layer/CREP-Metrik einen Ton nacheinander ab.
 */
export function playMandalaSoundscape(layers: CREPMetrics[], mode: 'mandala'|'phi' = 'mandala') {
  layers.forEach((crep, i) => {
    const freq = crepToFrequency(crep, 220, mode);
    setTimeout(() => {
      playPhiTone(freq, 0.35 + Math.random() * 0.15, 0.1 + Math.random() * 0.04);
    }, i * 160);
  });
}
```

