export const PHI = (1 + Math.sqrt(5)) / 2;
export const PI = Math.PI;
export const E = Math.E;

export type CREPMetrics = {
  coherence: number;
  resonance: number;
  emergence: number;
  poetics: number;
};

/**
 * Mapping: CREP/Skalen-Modi → Hz
 */
export function crepToFrequency(
  crep: CREPMetrics,
  base = 220,
  mode: 'phi' | 'pi' | 'e' | 'mandala' = 'phi'
): number {
  const { coherence, resonance, emergence, poetics } = crep;
  switch (mode) {
    case "phi":      return base * Math.pow(PHI, coherence);
    case "pi":       return base * Math.pow(PI, resonance / 2.5);
    case "e":        return base * Math.pow(E, emergence / 2.5);
    case "mandala":  return (
      base * Math.pow(PHI, coherence) +
      base * Math.pow(PI, resonance) / 2 +
      base * Math.pow(E, emergence) / 4 +
      10 * Math.sin(poetics * 2 * PI)
    );
    default: return base;
  }
}
