import fs from 'fs/promises';
import yaml from 'js-yaml';

/**
 * SigilManager lädt und speichert Sigillin (YAML) für den Agenten.
 */
export class SigilManager {
  private filePath: string;
  private sigil: any;

  constructor(filePath: string) {
    this.filePath = filePath;
  }

  async load(): Promise<any> {
    try {
      const content = await fs.readFile(this.filePath, 'utf8');
      this.sigil = yaml.load(content);
      return this.sigil;
    } catch (err) {
      // Datei existiert nicht oder parsing error
      return null;
    }
  }

  async write(event: string, data: any): Promise<void> {
    const entry = { timestamp: new Date().toISOString(), event, data };
    const dump = yaml.dump(entry);
    await fs.appendFile(this.filePath, dump + '\n---\n', 'utf8');
  }
}


