  additionalProperties: false
};

const ajv = new Ajv({ allErrors: true, useDefaults: true });
const validate = ajv.compile(theoryConfigSchema);

/**
 * Lädt und validiert die Agenten-Konfiguration (YAML oder JSON)
 * @param filePath Pfad zur Config-Datei
 */
export function loadConfig(filePath: string): TheoryAgentConfig {
  const ext = path.extname(filePath).toLowerCase();
  const raw = fs.readFileSync(filePath, 'utf-8');
  let data: any;

  if (ext === '.json') {
    data = JSON.parse(raw);
  } else if (ext === '.yaml' || ext === '.yml') {
    // yaml library import falls benötigt
    const YAML = require('yaml');
    data = YAML.parse(raw);
  } else {
    throw new Error(`Unsupported config format: ${ext}`);
  }

  if (!validate(data)) {
    throw new Error('Invalid TheoryAgentConfig:\n' + ajv.errorsText(validate.errors));
  }

  return data;
