// src/config/PyramidConfig.ts

import fs from 'fs';
import path from 'path';
import YAML from 'js-yaml';
import Ajv, { JSONSchemaType } from 'ajv';

/**
 * Interface für PyramidConfig (siehe Doku) 
 */
export interface PyramidConfig {
  totalLayers: number;
  nodesPerLayer: number;
  weightFactors: {
    coherence: number;
    resonance: number;
    emergence: number;
    poetics: number;
  };
}

// JSON-Schema für Validierung
const schema: JSONSchemaType<PyramidConfig> = {
  type: 'object',
  properties: {
    totalLayers: { type: 'integer', minimum: 1 },
    nodesPerLayer: { type: 'integer', minimum: 1 },
    weightFactors: {
      type: 'object',
      properties: {
        coherence: { type: 'number', minimum: 0 },
        resonance: { type: 'number', minimum: 0 },
        emergence: { type: 'number', minimum: 0 },
        poetics: { type: 'number', minimum: 0 }
      },
      required: ['coherence', 'resonance', 'emergence', 'poetics'],
      additionalProperties: false
    }
  },
  required: ['totalLayers', 'nodesPerLayer', 'weightFactors'],
  additionalProperties: false
};

const ajv = new Ajv();
const validate = ajv.compile(schema);

/**
 * Lädt und validiert eine Konfigurationsdatei (JSON oder YAML)
 * @param fileName Pfad zur Config-Datei
 */
export function loadConfig(fileName: string): PyramidConfig {
  const ext = path.extname(fileName);
  const raw = fs.readFileSync(fileName, 'utf-8');
  let data: any;

  if (ext === '.yaml' || ext === '.yml') {
    data = YAML.load(raw);
  } else if (ext === '.json') {
    data = JSON.parse(raw);
  } else {
    throw new Error(`Unsupported config format: ${ext}`);
  }

  if (!validate(data)) {
    throw new Error('Invalid PyramidConfig: ' + ajv.errorsText(validate.errors));
  }
  return data;
}

