```typescript
// src/error/ErrorRecoveryService.ts
import { EventEmitter } from 'events';
import { FallbackSynthesizer } from './FallbackSynthesizer';

export class ErrorRecoveryService {
  private emitter: EventEmitter;
  private fallback: FallbackSynthesizer;

  constructor(emitter: EventEmitter, audioContext?: AudioContext) {
    this.emitter = emitter;
    this.fallback = new FallbackSynthesizer(audioContext);
    this.setupListeners();
  }

  private setupListeners() {
    // Lausche auf systemweite Fehler-Events
    this.emitter.on('error', (err, module) => {
      console.error(`[Recovery] Error in ${module}:`, err);
      this.fallback.playFallbackTone();
      // Nach 1s Recovery-Versuch
      setTimeout(() => this.restartModule(module), 1000);
    });
  }

  private restartModule(module: string) {
    this.emitter.emit('restart', module);
    console.info(`[Recovery] Restart event emitted for module ${module}`);
  }
}
```

**Features dieses Scaffolds:**
- **FallbackSynthesizer** liefert immer einen akustischen Indikator, wenn KI/Audiokomponenten ausfallen.
- **ErrorRecoveryService** lauscht global auf `error`-Ereignisse, spielt den Fallback-Ton, und sendet nach kurzer Pause einen `restart`-Event.

