## 10. Fehler- und Zustandsmanagement – Vollständiges Scaffold

### 10.1 Core-Module

#### `FallbackSynthesizer.ts`

```typescript
// src/error/FallbackSynthesizer.ts
export class FallbackSynthesizer {
  private audioContext: AudioContext;

  constructor(sharedContext?: AudioContext) {
    // AudioContext einmalig anlegen oder wiederverwenden
    this.audioContext = sharedContext || new AudioContext();
  }

  /**
   * Spielt einen Ersatz-Ton, wenn KI- oder Audio-Komponenten ausfallen.
   * @param duration Dauer in Sekunden
   */
  playFallbackTone(duration = 0.5) {
    const osc = this.audioContext.createOscillator();
    osc.frequency.value = 220;    // tiefer, beruhigender Ton
    osc.type = 'sine';
    osc.connect(this.audioContext.destination);
    osc.start();
    osc.stop(this.audioContext.currentTime + duration);
  }
}
```

#### `ErrorRecoveryService.ts`

```typescript
// src/error/ErrorRecoveryService.ts
import { EventEmitter } from 'events';
import { FallbackSynthesizer } from './FallbackSynthesizer';

export class ErrorRecoveryService {
  constructor(
    private emitter: EventEmitter,
    private fallback = new FallbackSynthesizer()
  ) {
    this.setupListeners();
  }

  private setupListeners() {
    // Lausche auf systemweite Fehler
    this.emitter.on('error', (err: Error, module: string) => {
      console.error(`[Recovery] Fehler in Modul "${module}":`, err);

      // 1) Fallback-Audio
      this.fallback.playFallbackTone();

      // 2) UI-Benachrichtigung
      this.emitter.emit('ui:error', { module, message: err.message });

      // 3) Neustart-Event nach 1 Sekunde
      setTimeout(() => this.emitter.emit('restart', module), 1000);
    });
  }
}
```

