```tsx
// src/ui/ErrorMarker.tsx
import React, { useEffect, useState } from 'react';
import type { EventEmitter } from 'events';

interface ErrorEvent { module: string; message: string; }

export function ErrorMarker({ bus }: { bus: EventEmitter }) {
  const [errors, setErrors] = useState<ErrorEvent[]>([]);

  useEffect(() => {
    const onError = (e: ErrorEvent) => {
      setErrors(prev => [...prev, e]);
      // nach 3s ausblenden
      setTimeout(() => setErrors(prev => prev.slice(1)), 3000);
    };
    bus.on('ui:error', onError);
    return () => { bus.off('ui:error', onError); };
  }, [bus]);

  return (
    <div aria-live="assertive" className="error-marker-container">
      {errors.map((e, i) => (
        <div key={i} role="alert" className="error-marker">
          ⚠️ Fehler in <strong>{e.module}</strong>: {e.message}
        </div>
      ))}
    </div>
  );
}
```

**Accessibility-Notes:**

* `aria-live="assertive"` stellt sicher, dass Screenreader die Meldung sofort vorlesen.
* `role="alert"` macht jede Meldung semantisch korrekt.

