```typescript
// src/layers/Layer.ts
export interface Layer {
  /** Eindeutige ID */
  id: string;
  /** Level-Index (0 = Wurzel, größer = tiefer) */
  level: number;
  /** Kinder-Layer für Verschachtelung */
  children?: Layer[];
  /** Gewichtungsfaktor (z.B. Phi-basiert) */
  weight: number;
  /** Berechnet emergente Metadaten dieses Layers */
  analyze(): EmergenceMetrics;
}

