## 2. Gewichtung mit kosmischen Konstanten

Verwende Φ (Phi), π (Pi), e, α (Alpha) als Basis für Gewichtungs- und Skalierungsfunktionen:

```typescript
// src/layers/weights.ts
export const PHI = (1 + Math.sqrt(5)) / 2;
export const PI = Math.PI;
export const E  = Math.E;

// Beispielgewicht: exponential falloff mit Phi
export function phiWeight(level: number): number {
  return Math.pow(PHI, -level);
}

// Kombiniertes Gewicht: Phi, Pi, E
export function combinedWeight(level: number, factor: number): number {
  return phiWeight(level) * Math.sin(PI * factor) + Math.log1p(E * factor);
}
```

Beim Erstellen eines Layers setzt du das `weight`-Feld via `combinedWeight(level, someFactor)` – so fließt die kosmische Mathematik direkt in deine Strukturen ein.

---

## 3. Dynamische Layer-Generierung

Eine Utility, um automatisch `n` Layer-Tiefen mit `m` Unterteilungen pro Ebene zu erzeugen:

```typescript
import { Layer, EmergenceMetrics } from './Layer';
import { combinedWeight } from './weights';

export function generateNestedLayers(
  depth: number,
  subdivisions: number
): Layer {
  function build(level: number): Layer[] {
    if (level > depth) return [];
    return Array(subdivisions).fill(null).map((_, idx) => {
      const layer: Layer = {
        id: `L${level}-N${idx}`,
        level,
        weight: combinedWeight(level, (idx+1)/subdivisions),
        children: build(level + 1),
        analyze() {
          // Beispielanalyse: aggregiere Kinder-Metriken
          const childMetrics = this.children?.map(c => c.analyze()) ?? [];
          const sum = childMetrics.reduce((acc, m) => (
            { coherence: acc.coherence + m.coherence,
              resonance: acc.resonance + m.resonance,
              emergence: acc.emergence + m.emergence,
              poetics: acc.poetics + m.poetics
            }), { coherence: 0, resonance: 0, emergence: 0, poetics: 0 });
          // Basis-Metrik + gewichtete Kinder
          return {
            coherence: this.weight + sum.coherence,
            resonance: this.weight + sum.resonance,
            emergence: this.weight + sum.emergence,
            poetics: this.weight + sum.poetics
          };
        }
      };
      return layer;
    });
  }

  // Wrap in Root-Layer
  return {
    id: 'root',
    level: 0,
    weight: 1,
    children: build(1),
    analyze() {
      return this.children!.map(c => c.analyze()).reduce((a,b) => ({
        coherence: a.coherence + b.coherence,
        resonance: a.resonance + b.resonance,
        emergence: a.emergence + b.emergence,
        poetics: a.poetics + b.poetics
      }), { coherence:0, resonance:0, emergence:0, poetics:0 });
    }
  };
}
```

