```tsx
// src/ui/NestedPyramid.tsx
import React from 'react';
import { Canvas } from '@react-three/fiber';
import { Layer } from '../layers/Layer';

export function NestedPyramid({ root }: { root: Layer }) {
  function renderLayer(layer: Layer, parentPosition = [0,0,0]) {
    return (
      <group key={layer.id} position={parentPosition}>
        <mesh>
          <boxBufferGeometry args={[layer.weight, layer.weight, layer.weight]} />
          <meshStandardMaterial color={`hsl(${layer.level*30},50%,50%)`} />
        </mesh>
        {layer.children?.map((child, idx) =>
          renderLayer(child, [idx - layer.children!.length/2, -1, 0])
        )}
      </group>
    );
  }

  return (
    <Canvas camera={{ position: [0,5,10] }}>
      <ambientLight />
      {renderLayer(root)}
    </Canvas>
  );
}
```

