import { CREPManager } from 'crep-engine';
import TypedEmitter from 'typed-emitter';
import { v4 as uuidv4 } from 'uuid';
import pino from 'pino';
import CircuitBreaker from 'opossum';
import LRUCache from 'lru-cache';
import axios from 'axios';
import { context, trace, Span, Tracer } from '@opentelemetry/api';
import { loadCMBMap, loadNeutrinoFlux, CMBData, NeutrinoData } from '../data/CosmicDataLoader';
import { fractalDecompose, FractalOptions } from '../analysis/FractalAnalyzer';
import { boxCountDecompose } from '../analysis/BoxCountDecompose';
import { fourierDecompose } from '../analysis/FourierDecompose';
import { symbolicRegressor, FormulaCandidate, RegressionOptions } from '../analysis/SymbolicRegression';
import { registerHistogram, registerCounter } from '../observability/metrics';
import { loadConfig, TheoryAgentConfig } from '../config/TheoryAgentConfig';

/**
 * Events für den CosmicTheoryAgent mit Trace-Context
 */
interface TheoryEvents {
  'theory:start': (ctx: TheoryContext) => void;
  'theory:dataLoaded': (ctx: TheoryContext & { cmbSize: number; nuSize: number }) => void;
  'theory:fractals:generated': (ctx: TheoryContext & { depth: number }) => void;
  'theory:regression:success': (ctx: TheoryContext & { duration: number }) => void;
  'sigil_alert': (ctx: TheoryContext & { id: string; data?: any }) => void;
  'user:theory_feedback': (ctx: TheoryContext & { formula: string; rating: number }) => void;
}

type TheoryBus = TypedEmitter<TheoryEvents>;

/**
 * Kontext für verteiltes Tracing und Logs
 */
interface TheoryContext {
  requestId: string;
  timestamp: number;
  agentVersion: string;
  configVersion: string;
  userSessionId?: string;
  span?: Span;
}

export class CosmicTheoryAgent {
  private crep: CREPManager;
  private bus: TheoryBus;
  private config: TheoryAgentConfig;
  private logger;
  private breaker: CircuitBreaker;
  private tracer: Tracer;
  private cache: LRUCache<string, FormulaCandidate[]>;
  private agentVersion = '1.1.0';

  constructor(crep: CREPManager, bus: TheoryBus, configPath: string) {
    this.crep = crep;
    this.bus = bus;

    // 1) Config laden und validieren
    this.config = loadConfig(configPath);

    // 2) Logger mit Basis-Metadaten
    this.logger = pino({
      name: 'CosmicTheoryAgent',
      base: { agentVersion: this.agentVersion, configVersion: this.config.version }
    });

    // 3) Cache initialisieren
    this.cache = new LRUCache({ max: this.config.cacheSize });

    // 4) Tracer instanziieren
    this.tracer = trace.getTracer('CosmicTheoryAgent', this.agentVersion);

    // 5) Circuit Breaker mit konfigurierten Parametern
    this.breaker = new CircuitBreaker(
      (inputs: number[][], outputs: number[]) => symbolicRegressor(inputs, outputs, this.config.regression),
      {
        timeout: this.config.regression.timeout,
        errorThresholdPercentage: this.config.breakerErrorThreshold,
        resetTimeout: this.config.resetTimeout,
        rollingCountTimeout: this.config.rollingWindowMs,
        rollingCountBuckets: this.config.rollingBuckets
      }
    );

    // Circuit-Breaker-Events loggen
    this.breaker.on('open', () => this.logger.warn('Breaker geöffnet'));
    this.breaker.on('halfOpen', () => this.logger.info('Breaker halb-offen'));
    this.breaker.on('close', () => this.logger.info('Breaker geschlossen'));
    this.breaker.on('snapshot', stats => this.logger.debug({ stats }, 'Breaker snapshot'));
  }

  /**
   * Generiert Top-N Theoriekandidaten, nutzt Caching und Python-Fallback
   */
  async generateTheories(userContext?: { userSessionId?: string }): Promise<FormulaCandidate[]> {
    const requestId = uuidv4();
    const ctx: TheoryContext = {
      requestId,
      timestamp: Date.now(),
      agentVersion: this.agentVersion,
      configVersion: this.config.version,
      userSessionId: userContext?.userSessionId
    };
    const span = this.tracer.startSpan('generateTheories');
    ctx.span = span;

    this.bus.emit('theory:start', ctx);

    // Caching
    const cacheKey = `${this.config.depth}-${this.config.regression.maxDepth}`;
    if (this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey)!;
      // Hintergrund-Refresh
      this.refreshCache(cacheKey, ctx, span).catch(err => this.logger.error(err));
      span.end();
      return cached;
    }

    // Observability: Metriken
    const hist = registerHistogram({
      name: 'theory_generation_duration',
      labels: { agent: 'cosmic', version: this.agentVersion, method: this.config.fractalOptions.method }
    });
    const timer = hist.startTimer();
    registerCounter({ name: 'theory_generation_requests', labels: { agent: 'cosmic', method: this.config.fractalOptions.method } }).inc();

    // 1) Daten Asynchron laden
    let cmb: CMBData, neutrinos: NeutrinoData;
    try {
      [cmb, neutrinos] = await Promise.all([loadCMBMap(), loadNeutrinoFlux()]);
      this.bus.emit('theory:dataLoaded', { ...ctx, cmbSize: cmb.anisotropy.length, nuSize: neutrinos.flux.length });
    } catch (err) {
      this.logger.error({ err, requestId }, 'Datenladung fehlgeschlagen');
      this.bus.emit('sigil_alert', { ...ctx, id: this.config.sigilAlert.dataMissing });
      timer(); span.end();
      return [];
    }

    if (!cmb.anisotropy.length || !neutrinos.flux.length) {
      this.logger.warn({ requestId }, 'Leere Daten, überspringe Analyse');
      this.bus.emit('sigil_alert', { ...ctx, id: this.config.sigilAlert.dataMissing });
      timer(); span.end();
      return [];
    }

    // 2) Fraktale Zerlegung
    const fractalFn = this.getFractalMethod(this.config.fractalOptions.method);
    const cmbLayers = fractalFn(cmb.anisotropy, this.config.fractalOptions);
    const nuLayers = fractalFn(neutrinos.flux, this.config.fractalOptions);
    this.bus.emit('theory:fractals:generated', { ...ctx, depth: this.config.fractalOptions.depth });

    const inputs = cmbLayers.map((m, i) => [i, m.emergence]);
    const outputs = cmbLayers.map(m => m.coherence);

    // 3) Regression mit Circuit Breaker
    let candidates: FormulaCandidate[];
    try {
      candidates = await this.breaker.fire(inputs, outputs);
    } catch (err) {
      this.logger.warn({ err, requestId }, 'JS-Regression fehlgeschlagen, Python-Fallback');
      candidates = await this.callPythonService(inputs, outputs);
    }

    this.bus.emit('theory:regression:success', { ...ctx, duration: timer() });

    // 4) Scoring & Filter
    const scored = candidates.map(c => ({ ...c, poetics: this.crep.evaluatePoetics(c.expression) }));

    // 5) Sigil-Alert
    const best = scored.sort((a, b) => a.error - b.error)[0];
    if (best?.poetics! >= this.config.sigilAlert.minPoetics) {
      this.bus.emit('sigil_alert', { ...ctx, id: this.config.sigilAlert.success, data: best });
    }

    // 6) Cache setzen und Return
    this.cache.set(cacheKey, scored.slice(0, this.config.topN));
    span.end();
    return scored.slice(0, this.config.topN);
  }

  /** Holt die korrekte Zerlegungsfunktion */
  private getFractalMethod(name: string) {
    const methods: Record<string, (data: number[], opts: FractalOptions) => any[]> = {
      wavelet: fractalDecompose,
      boxCount: boxCountDecompose,
      fourier: fourierDecompose
    };
    return methods[name] || fractalDecompose;
  }

  /** Python-Microservice-Aufruf als Fallback */
  private async callPythonService(inputs: number[][], outputs: number[]): Promise<FormulaCandidate[]> {
    const { url, timeout } = this.config.pythonFallback;
    const resp = await axios.post(url, { inputs, outputs }, { timeout });
    return resp.data as FormulaCandidate[];
  }

  /** Hintergrund-Refresh des Caches ohne Event-Loop-Block */
  private async refreshCache(key: string, ctx: TheoryContext, parentSpan?: Span) {
    const span = this.tracer.startSpan('refreshCache', { parent: parentSpan });
    try {
      const fresh = await this.generateTheories({ userSessionId: ctx.userSessionId });
      this.cache.set(key, fresh);
    } catch (err) {
      this.logger.warn({ err, requestId: ctx.requestId }, 'RefreshCache fehlgeschlagen');
    } finally {
      span.end();
    }
  }
}
