```tsx
// packages/ui/src/components/ThreeDPyramid.tsx
import React, { useEffect, useState } from 'react';
import { useFrame } from '@react-three/fiber';
import { Layer } from 'common/layers/Layer';
import { generateNestedLayers } from 'common/layers/generateNestedLayers';

export function ThreeDPyramid() {
  const [root] = useState<Layer>(() => generateNestedLayers(4, 5));

  return <group>{renderLayer(root, 0)}</group>;
}

function renderLayer(layer: Layer, idxOffset: number) {
  return (
    <group key={layer.id} position={[idxOffset * 1.5, -layer.level, 0]}> 
      <mesh>
        <boxGeometry args={[layer.weight, layer.weight, layer.weight]} />
        <meshStandardMaterial color={`hsl(${layer.level * 30}, 60%, 50%)`} />
      </mesh>
      {layer.children?.map((c, i) => renderLayer(c, idxOffset + i - layer.children!.length / 2))}
    </group>
  );
}
