```ts
// packages/ui/src/audio/PhiTone.tsx
import React, { createContext, useContext, useMemo } from 'react';

const AudioContextCtx = createContext<AudioContext | null>(null);

export const AudioContextProvider: React.FC = ({ children }) => {
  const ctx = useMemo(() => new AudioContext(), []);
  return <AudioContextCtx.Provider value={ctx}>{children}</AudioContextCtx.Provider>;
};

export function usePhiTone(frequencyMultiplier: number) {
  const ctx = useContext(AudioContextCtx)!;
  return (value: number) => {
    const osc = ctx.createOscillator();
    osc.frequency.value = value * frequencyMultiplier;
    osc.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.5);
  };
}
