```ts
// packages/ui/src/audio/PhiTone.tsx
import React, { createContext, useContext, useMemo } from 'react';

const AudioCtx = createContext<AudioContext | null>(null);

export const AudioContextProvider: React.FC = ({ children }) => {
  const ctx = useMemo(() => new AudioContext(), []);
  return <AudioCtx.Provider value={ctx}>{children}</AudioCtx.Provider>;
};

export function usePhiTone(multiplier: number) {
  const ctx = useContext(AudioCtx)!;
  return (baseFreq: number) => {
    const osc = ctx.createOscillator();
    osc.frequency.value = baseFreq * multiplier;
    osc.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.3);
  };
}
```

