}

function renderLayer(layer: Layer, offset: number) {
  return (
    <group key={layer.id} position={[offset * 1.2, -layer.level, 0]}> 
      <mesh>
        <boxGeometry args={[layer.weight, layer.weight, layer.weight]} />
        <meshStandardMaterial color={`hsl(${layer.level * 30}, 60%, 50%)`} />
      </mesh>
      {layer.children?.map((child, idx) =>
        renderLayer(child, offset + idx - (layer.children!.length - 1) / 2)
      )}
    </group>
  );
}
