// packages/ui/src/hooks/useGenerateTheories.ts
import { useState } from 'react';

export function useGenerateTheories() {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any[]>([]);

  async function generate(params: { depth: number; subdivisions: number }) {
    setLoading(true);
