### 6.2 Frontend-Hook `useGenerateTheories`

```ts
// packages/ui/src/hooks/useGenerateTheories.ts
import { useState } from 'react';

export function useGenerateTheories() {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any[]>([]);

  async function generate(params: { depth: number; subdivisions: number }) {
    setLoading(true);
    const res = await fetch('/api/generate', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(params)
    });
    const data = await res.json();
    setResult(data.formulas);
    setLoading(false);
  }

  return { generate, result, loading };
}
```

