### 7.3 Telemetry-Dashboard im UI

```tsx
// packages/ui/src/components/TelemetryDashboard.tsx
import React, { useEffect, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip } from 'recharts';

export function TelemetryDashboard() {
  const [data, setData] = useState<any[]>([]);
  useEffect(() => {
    const interval = setInterval(async () => {
      const resp = await fetch('/metrics');
      const text = await resp.text();
      // parse Prometheus metrics into chart data
      const parsed = text.split('
').filter(l => l.startsWith('theory_generation_duration')).map(line => {
        const [metric, value] = line.split(' ');
        return { metric, value: Number(value) };
      });
      setData(parsed);
    }, 5000);
    return () => clearInterval(interval);
  }, []);
  return (
    <LineChart width={300} height={200} data={data}>
      <XAxis dataKey="metric" />
      <YAxis />
      <Tooltip />
      <Line type="monotone" dataKey="value" />
    </LineChart>
  );
}
```

